actions.script:
def raw = subdomain?.trim()?.toLowerCase()
canonical = raw
valid = false
available = false
if (!raw) { reason = 'Please enter a workspace URL.'; return }
// 3-30 chars, lowercase letters/digits/hyphens, cannot start or end with a hyphen
if (!(raw ==~ /[a-z0-9][a-z0-9-]{1,28}[a-z0-9]/)) {
    reason = 'Use 3-30 characters: lowercase letters, numbers and hyphens only (cannot start or end with a hyphen).'
    return
}
if (raw.contains('--')) { reason = 'A workspace URL cannot contain two hyphens in a row.'; return }
def reserved = ['www','admin','api','app','apps','qapps','vapps','rest','login','logout',
    'signup','signin','get-started','dashboard','mail','smtp','imap','pop','ftp','root',
    'system','sys','support','help','billing','pay','payment','static','cdn','assets',
    'zenithstatic','ns1','ns2','status','blog','test','demo','moqui','zeta','zetaerp','zenith'] as Set
if (reserved.contains(raw)) { reason = "'" + raw + "' is reserved. Please choose another."; return }
valid = true
def tenantCnt = ec.entity.find('zenith.erp.saas.SaasTenant')
    .condition('subdomain', raw).disableAuthz().count()
def codeCnt = ec.entity.find('mantle.party.PartyIdentification')
    .condition('partyIdTypeEnumId','PtidOrgCode').condition('idValue', raw.toUpperCase())
    .disableAuthz().count()
if (tenantCnt > 0 || codeCnt > 0) {
    reason = "'" + raw + "' is already taken. Please choose another."; return
}
available = true
reason = 'Available'

if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Only the ZetaERP super admin can extend a trial."); return }
def tenant = ec.entity.find("zenith.erp.saas.SaasTenant").condition("tenantId", tenantId).forUpdate(true).disableAuthz().one()
if (!tenant) { ec.message.addError("Tenant not found."); return }
if (tenant.organizationPartyId == '100000') { ec.message.addError("MARUTHI (100000) is protected and is not a trial tenant."); return }
if (ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',tenantId)
        .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()?.configValue) {
    ec.message.addError('Use Tenant Plans to extend manually assigned access.'); return
}
int days = (trialDays ?: 14) as int
if (days < 1) days = 1
if (days > 365) days = 365
def nowTs = ec.user.nowTimestamp
def newEnd = new java.sql.Date(nowTs.getTime() + (days * 86400000L))
// Extend a still-live trial in place; otherwise create a fresh SubTrial (revive from expired/none).
def liveTrial = ec.entity.find("zenith.erp.saas.SaasSubscription").condition("tenantId", tenantId)
    .condition("statusId", "SubTrial").orderBy("-startDate").orderBy("-lastUpdatedStamp").disableAuthz().list()
if (liveTrial) {
    ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
        .parameters([subscriptionId: liveTrial[0].subscriptionId, trialEndDate: newEnd, renewalDate: newEnd, endDate: null]).disableAuthz().call()
} else {
    def prev = ec.entity.find("zenith.erp.saas.SaasSubscription").condition("tenantId", tenantId)
        .orderBy("-startDate").orderBy("-lastUpdatedStamp").disableAuthz().list()
    def base = prev ? prev[0] : null
    def plan = ec.entity.find("zenith.erp.saas.SaasPlan").condition("planId", tenant.planId).disableAuthz().one()
    ec.service.sync().name("create#zenith.erp.saas.SaasSubscription").parameters([
        tenantId: tenantId, planId: tenant.planId, statusId: 'SubTrial',
        billingCycle: base?.billingCycle ?: 'Monthly', startDate: new java.sql.Date(nowTs.getTime()),
        trialEndDate: newEnd, renewalDate: newEnd, autoRenew: 'N',
        amount: plan?.monthlyPrice ?: (base?.amount ?: 0), currencyUomId: tenant.currencyUomId
    ]).disableAuthz().call()
}
// Reactivate the tenant so it regains access. Use SaasTenantActive (the ONLY valid target from
// Suspended/Trial in the SaasTenant status flow — Suspended->Trial is NOT an allowed transition);
// the SubTrial subscription + future trialEndDate is the authoritative trial state (the daily
// check#TrialExpiry cron re-suspends when it lapses). Skip the update if already Active (no-op).
if (tenant.statusId != 'SaasTenantActive') {
    ec.service.sync().name("update#zenith.erp.saas.SaasTenant").parameters([tenantId: tenantId, statusId: 'SaasTenantActive']).disableAuthz().call()
}
def _fmt = new java.text.SimpleDateFormat('dd-MMM-yyyy').format(newEnd)
ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog").parameters([
    tenantId: tenantId, eventType: 'TRIAL_EXTENDED', eventDate: nowTs, userId: ec.user.userId,
    description: 'Trial extended ' + days + ' days (until ' + _fmt + ')'
]).disableAuthz().call()
newTrialEndDate = newEnd
ec.message.addMessage('Trial extended ' + days + ' days — until ' + _fmt + '.')

import java.time.LocalDate
def today = LocalDate.now()
def renewal = billingCycle == 'Yearly' ? today.plusYears(1) : today.plusMonths(1)
// A mid-cycle change must not reset prepaid time or grant a fresh free period.
context.renewalDate = curSub?.renewalDate ?: java.sql.Date.valueOf(renewal)
context.periodStart = curSub?.startDate ?: ec.user.nowTimestamp

if.script:
def diff = ((subAmount ?: 0) as BigDecimal) - (prorationBase as BigDecimal)
context.proratedDiff = 0.0
if (diff > 0 && curSub.renewalDate != null) {
    def _prToday = java.time.LocalDate.now()
    def _prRenew = new java.sql.Date(curSub.renewalDate.getTime()).toLocalDate()
    def _prStart = curSub.startDate != null ? new java.sql.Date(curSub.startDate.getTime()).toLocalDate() : _prRenew.minusMonths(1)
    long cycleDays = Math.max(1L, java.time.temporal.ChronoUnit.DAYS.between(_prStart, _prRenew))
    long remainingDays = java.time.temporal.ChronoUnit.DAYS.between(_prToday, _prRenew)
    if (remainingDays < 0) remainingDays = 0
    if (remainingDays > cycleDays) remainingDays = cycleDays
    context.proratedDiff = ((diff * remainingDays) / cycleDays).setScale(2, java.math.RoundingMode.HALF_UP)
}

actions.script:
import java.time.LocalDate
def now = LocalDate.now()
def pm = (now.year * 100) + now.monthValue

import groovy.json.JsonSlurper
context.verified = false
// Our expected audience = configured Google Web Client ID
def cfg = ec.entity.find("zenith.erp.base.CompanySettings")
    .condition("organizationPartyId","ZETAERP").condition("settingKey","GOOGLE_CLIENT_ID").one()
def expectedAud = cfg?.settingValue
if (!expectedAud) { ec.message.addError("Google sign-in is not configured."); return }

def body
try {
    def url = new URL("https://oauth2.googleapis.com/tokeninfo?id_token=" + java.net.URLEncoder.encode(idToken, "UTF-8"))
    def conn = (java.net.HttpURLConnection) url.openConnection()
    conn.setRequestMethod("GET"); conn.setConnectTimeout(5000); conn.setReadTimeout(5000)
    def code = conn.responseCode
    if (code != 200) { ec.message.addError("Could not verify Google sign-in. Please try again."); return }
    body = conn.inputStream.getText("UTF-8")
} catch (Exception e) { ec.message.addError("Could not verify Google sign-in. Please try again."); return }
def claims = new JsonSlurper().parseText(body)

def iss = claims.iss
if (iss != "accounts.google.com" && iss != "https://accounts.google.com") { ec.message.addError("Invalid Google token issuer."); return }
if (claims.aud != expectedAud) { ec.message.addError("Google token was issued for a different application."); return }
def expSec = (claims.exp ?: "0") as long
if (expSec * 1000L < System.currentTimeMillis()) { ec.message.addError("Google sign-in expired. Please try again."); return }
if (!("true".equals(String.valueOf(claims.email_verified)))) { ec.message.addError("Your Google email is not verified."); return }

context.email = claims.email
context.firstName = claims.given_name ?: ""
context.lastName = claims.family_name ?: ""
context.googleSub = claims.sub
context.verified = true

context.sent = false
def em = email?.trim()?.toLowerCase()
if (!em) return
def ua = ec.entity.find("moqui.security.UserAccount").condition("username", em).disableAuthz().one()
if (ua == null) return
def uid = ua.userId
def ev = ec.entity.find("moqui.security.UserPreference").condition("userId", uid)
    .condition("preferenceKey", "EMAIL_VERIFIED").disableAuthz().one()
if (ev?.preferenceValue == "Y") return   // already verified: nothing to send
def token = java.util.UUID.randomUUID().toString().replace("-", "")
ec.entity.makeValue("moqui.security.UserPreference")
    .setAll([userId:uid, preferenceKey:"EMAIL_VERIFIED", preferenceValue:"N"]).createOrUpdate()
ec.entity.makeValue("moqui.security.UserPreference")
    .setAll([userId:uid, preferenceKey:"EMAIL_VERIFY_TOKEN", preferenceValue:token]).createOrUpdate()
def verifyUrl = "https://erp.zetaclantech.com/Login/verifyEmail?token=" + token
try {
    ec.service.sync().name("org.moqui.impl.EmailServices.send#EmailTemplate")
        .parameters([emailTemplateId:"EMAIL_VERIFY", toAddresses:em,
            bodyParameters:[verifyUrl:verifyUrl, firstName:(firstName ?: ua.userFullName ?: "")]])
        .disableAuthz().call()
    context.sent = true
} catch (Exception e) {
    ec.logger.error("EMAIL_VERIFY send failed for " + em + ": " + e.message)
}
